export const dynamic = "force-dynamic";
// Route Handler: GET /api/email-action
//
// Target of the Approve / Decline buttons in admin approval emails.
// The admin is usually not logged in when they click, so authentication is
// carried by a signed token embedded in the link: HMAC-SHA256 over
// `${booking_id}:${action}` with EMAIL_ACTION_SECRET, generated by the
// send-notification Edge Function when the email is rendered.
//
// This handler does not verify the token itself. It forwards booking_id,
// action and token unchanged to the approve-guest Edge Function, which
// verifies the HMAC and refuses bookings that are no longer pending.
// No service-role credential is used here on purpose.
//
// Query params:
//   booking_id — UUID of the booking to approve/decline
//   action     — "approve" | "decline"
//   token      — signed token from the email link
//
// On success → 302 to /approvals?success=…
// On error   → 302 to /approvals?error=…

import { NextRequest, NextResponse } from "next/server";

const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL!;
const SUPABASE_ANON_KEY = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!;

const ADMIN_ORIGIN =
  process.env.NEXT_PUBLIC_APP_URL ?? "https://admin.terrazasports.com";

function redirect(path: string) {
  return NextResponse.redirect(new URL(path, ADMIN_ORIGIN));
}

export async function GET(req: NextRequest) {
  const { searchParams } = new URL(req.url);
  const bookingId = searchParams.get("booking_id");
  const action = searchParams.get("action");
  const token = searchParams.get("token");

  if (!bookingId || !action || !token) {
    return redirect("/approvals?error=invalid_link");
  }
  if (action !== "approve" && action !== "decline") {
    return redirect("/approvals?error=invalid_action");
  }

  try {
    const res = await fetch(`${SUPABASE_URL}/functions/v1/approve-guest`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        // The Edge Functions gateway requires a Supabase JWT; the public anon
        // key satisfies that. Authorisation for the action itself is the token.
        Authorization: `Bearer ${SUPABASE_ANON_KEY}`,
        apikey: SUPABASE_ANON_KEY,
      },
      body: JSON.stringify({ booking_id: bookingId, action, token }),
    });

    if (!res.ok) {
      const body = await res.json().catch(() => ({}));
      const msg = (body as { error?: string }).error ?? "unknown_error";
      console.error(`approve-guest returned ${res.status}: ${msg}`);
      return redirect(`/approvals?error=${encodeURIComponent(msg)}`);
    }

    return redirect(
      `/approvals?success=${action === "approve" ? "booking_approved" : "booking_declined"}`
    );
  } catch (e) {
    console.error("email-action handler failed:", e);
    return redirect("/approvals?error=network_error");
  }
}
